def set_cell_shading(cell, fill):
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement("w:shd")
    shd.set(qn("w:fill"), fill)
    tc_pr.append(shd)


def set_font(run, name="Aptos", size=11, bold=False, color="273833"):
    run.font.name = name
    run._element.get_or_add_rPr().rFonts.set(qn("w:ascii"), name)
    run._element.get_or_add_rPr().rFonts.set(qn("w:hAnsi"), name)
    run.font.size = Pt(size)
    run.bold = bold
    run.font.color.rgb = RGBColor.from_string(color)


def add_text(doc, text, size=11, bold=False, color="273833", align=None, after=8, line=1.18):
    p = doc.add_paragraph()
    if align is not None:
        p.alignment = align
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(after)
    p.paragraph_format.line_spacing = line
    r = p.add_run(text)
    set_font(r, size=size, bold=bold, color=color)
    return p


def create_bio(bio):
    doc = Document()
    section = doc.sections[0]
    section.page_width = Inches(8.5)
    section.page_height = Inches(11)
    section.top_margin = Inches(0.85)
    section.bottom_margin = Inches(0.85)
    section.left_margin = Inches(0.9)
    section.right_margin = Inches(0.9)
    section.header_distance = Inches(0.35)
    section.footer_distance = Inches(0.4)

    normal = doc.styles["Normal"]
    normal.font.name = "Aptos"
    normal._element.rPr.rFonts.set(qn("w:ascii"), "Aptos")
    normal._element.rPr.rFonts.set(qn("w:hAnsi"), "Aptos")
    normal.font.size = Pt(11)
    normal.font.color.rgb = RGBColor.from_string("273833")
    normal.paragraph_format.space_after = Pt(8)
    normal.paragraph_format.line_spacing = 1.18

    header = section.header.paragraphs[0]
    header.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    run = header.add_run("MENTALIA | ΒΙΟΓΡΑΦΙΚΟ")
    set_font(run, size=8.5, bold=True, color="60766E")

    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.LEFT
    title.paragraph_format.space_before = Pt(14)
    title.paragraph_format.space_after = Pt(4)
    run = title.add_run(bio["name"])
    set_font(run, size=25, bold=True, color="183D36")

    role = add_text(doc, bio["role"], size=13.5, bold=True, color="416B5F", after=2)
    role.paragraph_format.keep_with_next = True
    unit = add_text(doc, bio["mentalia"], size=10.5, bold=True, color="6C7D77", after=16)
    unit.paragraph_format.keep_with_next = True

    band = doc.add_table(rows=1, cols=1)
    band.autofit = False
    band.columns[0].width = Inches(6.7)
    cell = band.cell(0, 0)
    set_cell_shading(cell, "E2E8CA")
    cell.width = Inches(6.7)
    p = cell.paragraphs[0]
    p.paragraph_format.space_before = Pt(5)
    p.paragraph_format.space_after = Pt(5)
    r = p.add_run("ΕΠΑΓΓΕΛΜΑΤΙΚΟ ΠΡΟΦΙΛ")
    set_font(r, size=9, bold=True, color="355D53")
    doc.add_paragraph().paragraph_format.space_after = Pt(2)

    split_at = 4 if len(bio["paragraphs"]) >= 7 else None
    for index, text in enumerate(bio["paragraphs"]):
        if split_at is not None and index == split_at:
            doc.add_page_break()
        p = add_text(doc, text, size=11, color="273833", after=9, line=1.2)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p.paragraph_format.first_line_indent = Inches(0.22)
        p.paragraph_format.widow_control = True

    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = footer.add_run("MENTALIA • Κέντρο Ψυχικής Υγείας και Προσωπικής Ανάπτυξης")
    set_font(r, size=8, color="7A8B85")

    props = doc.core_properties
    props.title = f"{bio['name']} | Βιογραφικό Mentalia"
    props.subject = "Επαγγελματικό βιογραφικό"
    props.author = "MENTALIA"

    path = OUT / bio["filename"]
    doc.save(path)
    return path


def main():
    OUT.mkdir(exist_ok=True)
    for bio in BIOS:
        path = create_bio(bio)
        print(path)


if __name__ == "__main__":
    main()
